import{bQ as e,aL as a,u as r,G as d}from"./chunks/framework.C1gZXFVa.js";const o="/assets/050101.Bv0t06oB.png",b=JSON.parse('{"title":"撮合初始化链路","description":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。","frontmatter":{"title":"撮合初始化链路","description":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070505"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070505"}],["meta",{"property":"og:title","content":"撮合初始化链路 · TGEX"}],["meta",{"property":"og:description","content":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"撮合初始化链路 · TGEX"}],["meta",{"name":"twitter:description","content":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"撮合初始化链路\\",\\"description\\":\\"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070505\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070505\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070505.md","filePath":"07.现货手册/05.核心流程/05.撮合初始化链路.md"}'),n={name:"pages/070505.md"};function h(i,t,s,p,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="撮合初始化链路" tabindex="-1">撮合初始化链路 <a class="header-anchor" href="#撮合初始化链路" aria-label="Permalink to &quot;撮合初始化链路&quot;">​</a></h1><div class="doc-lead">进程起来后：先备好通道与规则，再按交易对把未完结委托挂回盘口，最后才对该对开放下单与撤单。</div><p align="center"><img src="'+o+'" alt="撮合初始化链路"></p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>进程已起来</td><td>全局撮合通道可用，<strong>不等于</strong>每个交易对都能下单</td></tr><tr><td>某交易对已开放</td><td>该对未完结委托已挂回订单簿，可接受新的下单 / 撤单</td></tr></tbody></table><p>下文按上图节点展开。开放接单之后的实时下单 / 撤单见<a href="/pages/070508">撮合主流程</a>。</p><h2 id="_1-全局撮合通道就绪" tabindex="-1">1. 全局撮合通道就绪 <a class="header-anchor" href="#_1-全局撮合通道就绪" aria-label="Permalink to &quot;1. 全局撮合通道就绪&quot;">​</a></h2><p>准备全局事件通道与订单簿基础设施（依赖 Redis）。<br> 整站可处理内部事件；若后续「未落库刷库」多次失败，可能关掉全局通道，表现为暂时整站拒写。</p><h2 id="_2-redis-未落库增量-→-mysql" tabindex="-1">2. Redis 未落库增量 → MySQL <a class="header-anchor" href="#_2-redis-未落库增量-→-mysql" aria-label="Permalink to &quot;2. Redis 未落库增量 → MySQL&quot;">​</a></h2><p>启动时<strong>同步</strong>消化：上次异常停机留在 Redis 队列、尚未写入 MySQL 的增量（账户、委托、明细一类）。</p><p>目的：先把「上次没落完的账」尽量落完，再恢复盘口。刷完后另起后台任务持续消费 Redis → 库，与按交易对恢复并行。</p><h2 id="_3-拉取交易对与商户规则" tabindex="-1">3. 拉取交易对与商户规则 <a class="header-anchor" href="#_3-拉取交易对与商户规则" aria-label="Permalink to &quot;3. 拉取交易对与商户规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>用途</th></tr></thead><tbody><tr><td>平台交易对</td><td>有哪些 symbol、买卖币</td></tr><tr><td>商户启用交易对</td><td>哪些商户开了哪些对</td></tr></tbody></table><p><strong>没有可用交易对，后面无法按对恢复，也无法开放接单。</strong></p><h2 id="_4-装入禁交易-·-手续费-·-分成" tabindex="-1">4. 装入禁交易 · 手续费 · 分成 <a class="header-anchor" href="#_4-装入禁交易-·-手续费-·-分成" aria-label="Permalink to &quot;4. 装入禁交易 · 手续费 · 分成&quot;">​</a></h2><p>在启用商户列表上继续装入：禁止交易用户、平台币抵扣、商户分成、VIP 费率等。启动时先拉齐，避免「第一笔成交才去拼费率」。</p><h2 id="_5-装入价格参考" tabindex="-1">5. 装入价格参考 <a class="header-anchor" href="#_5-装入价格参考" aria-label="Permalink to &quot;5. 装入价格参考&quot;">​</a></h2><p>币种人民币价、各交易对最近成交价等，供撮合侧价格参考与折算。</p><h2 id="_6-按交易对并行-挂回订单簿" tabindex="-1">6. 按交易对并行：挂回订单簿 <a class="header-anchor" href="#_6-按交易对并行-挂回订单簿" aria-label="Permalink to &quot;6. 按交易对并行：挂回订单簿&quot;">​</a></h2><p>对每个交易对（并行）大致：创建该对引擎 → 暂时关闭接单 → 读未完结委托 → 挂回订单簿。</p><table tabindex="0"><thead><tr><th>路径</th><th>数据来源</th><th>适用</th></tr></thead><tbody><tr><td>热恢复</td><td>Redis 中该对未完结委托</td><td>常见重启</td></tr><tr><td>冷恢复</td><td>MySQL 未成交 / 部分成交</td><td>首次或标记要求走库</td></tr></tbody></table><p>热恢复时还会按需补齐相关用户币币资产到本地缓存，并刷新深度。另有非交易对通道（充提、改账等）不挂普通买卖盘。</p><h2 id="_7-开放接单或失败重试" tabindex="-1">7. 开放接单或失败重试 <a class="header-anchor" href="#_7-开放接单或失败重试" aria-label="Permalink to &quot;7. 开放接单或失败重试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结果</th><th>行为</th></tr></thead><tbody><tr><td>成功</td><td><strong>开放该交易对接单</strong>，可下单 / 撤单</td></tr><tr><td>失败</td><td>进入失败集合，定时重试；成功前该对应拒单</td></tr></tbody></table><p>主流程只保证「各对恢复任务已提交」，<strong>不保证</strong>全部交易对同一时刻都已开放。常见情况：有的对已开放，有的对仍在重试。</p><p>若环境启用高频策略，还会从 Redis 恢复当日卖单计数等附属数据。运行期仍会定时刷新交易对、分成、汇率等。</p><h2 id="就绪怎么理解" tabindex="-1">就绪怎么理解 <a class="header-anchor" href="#就绪怎么理解" aria-label="Permalink to &quot;就绪怎么理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>能做什么</th></tr></thead><tbody><tr><td>全局通道</td><td>内部事件通道可用</td></tr><tr><td>规则就绪</td><td>具备按规则处理的前提</td></tr><tr><td>单交易对开放</td><td>可接受该对下单 / 撤单</td></tr><tr><td>部分未完成</td><td>这些对暂时不可交易</td></tr></tbody></table><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>依赖</th><th>用途</th></tr></thead><tbody><tr><td>Redis / MySQL</td><td>未落库队列、热委托、冷恢复、刷库目标</td></tr><tr><td>交易对 / 商户 / 用户 / 账务 / 行情</td><td>清单、禁交易、费率、钱包快照、最近价</td></tr></tbody></table><p>建议：账务、交易对、行情至少部分可用后，再观察「按交易对是否已开放」。资金与成交教学见<a href="/pages/0701#complete">业务概述 · 案例</a>；比价时序见<a href="/pages/070508">撮合主流程</a>。</p><p>同组：<a href="/pages/070504">委托初始化链路</a> · <a href="/pages/070506">账务初始化链路</a> · <a href="/pages/070507">行情初始化链路</a> · <a href="/pages/070508">撮合主流程</a></p>',32)])])}const m=e(n,[["render",h]]);export{b as __pageData,m as default};
